mapper.select:
SELECT tenant_id AS tenantId,intent_id AS intentId,source_system AS sourceSystem,
  source_request_id AS sourceRequestId,delivery_mode AS deliveryMode,benefit_order_no AS benefitOrderNo,payload_json AS payload
FROM mk_award_intent_outbox WHERE tenant_id=#{tenantId} AND intent_id=#{intentId}

mapper.update:
UPDATE mk_award_fulfillment SET sync_state='PENDING',failure_count=0,lease_version=lease_version+1,next_attempt_at=#{now},updated_at=#{now}
WHERE tenant_id=#{tenantId} AND intent_id=#{intentId}
  AND (sync_state != 'RUNNING' OR lease_until <= #{now})

UPDATE mk_award_fulfillment SET sync_state='RUNNING',lease_owner=#{owner},lease_until=#{until},
  lease_version=lease_version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND intent_id=#{intentId} AND lease_version=#{expectedVersion}
  AND ((sync_state='PENDING' AND next_attempt_at <= #{now})
    OR (sync_state='RUNNING' AND lease_until <= #{now}))

UPDATE mk_award_fulfillment SET sync_state=#{state},failure_count=#{failures},error_code=#{errorCode},
  next_attempt_at=#{nextAttemptAt},updated_at=#{now},lease_owner=NULL,lease_until=NULL

  ,benefit_order_no=#{orderNo},center_status=#{centerStatus},items_json=#{itemsJson},checked_at=#{checkedAt}

WHERE tenant_id=#{tenantId} AND intent_id=#{intentId} AND sync_state='RUNNING'
  AND lease_owner=#{owner} AND lease_version=#{leaseVersion} AND lease_until > #{now}
